import{_ as s,o as n,c as e,a0 as l}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"关机与重启命令","description":"","frontmatter":{},"headers":[],"relativePath":"linux/poweroff.md","filePath":"linux/poweroff.md","lastUpdated":1791039142000}'),o={name:"linux/poweroff.md"};function i(t,a,p,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="关机与重启命令" tabindex="-1">关机与重启命令 <a class="header-anchor" href="#关机与重启命令" aria-label="Permalink to &quot;关机与重启命令&quot;">​</a></h1><p>直接断掉电源的方式来关闭linux，这是十分危险的。因为linux与windows不同，其后台运行着许多进程，所以强制关机可能会导致进程的 数据丢失,使系统处于不稳定的状态,甚至在有的系统中会损坏硬件设备。</p><h2 id="shutdown" tabindex="-1">shutdown <a class="header-anchor" href="#shutdown" aria-label="Permalink to &quot;shutdown&quot;">​</a></h2><p>系统关机前使用shutdown命令,系统管理员会通知所有登录的用户系统将要关闭,并且login指令会被冻结,即新的用户不能再登录。直接关 机或者延迟一定的时间才关机都是可能的,还可能重启。这是由所有进程〔process〕都会收到系统所送达的信号〔signal〕决定的。这让 像vi之类的程序有时间储存目前正在编辑的文档,而像处理邮件〔mail〕和新闻〔news〕的程序则可以正常地离开等等。 shutdown执行它 的工作是送信号〔signal〕给init程序,要求它改变runlevel。</p><ul><li><code>runlevel 0</code> 被用来停机〔halt〕</li><li><code>runlevel 6</code> 是用来重新激活〔reboot〕系统</li><li><code>runlevel 1</code> 则是被用来让系统进入管理工作可以进行的状态</li></ul><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">shutdown [选项] [时间]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>-c</code> 取消前一个关机命令</li><li><code>-h</code> 关机后关闭电源〔halt〕</li><li><code>-r</code> 重启</li></ul><p>在某个时间关机</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">shutdown </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">h </span><span style="color:#005CC5;">02</span><span style="color:#24292E;">:</span><span style="color:#005CC5;">15</span><span style="color:#6A737D;">       //执行这个命令后就不能再进行其他的操作</span></span>
<span class="line"><span style="color:#24292E;">shutdown </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">h </span><span style="color:#005CC5;">02</span><span style="color:#24292E;">:</span><span style="color:#005CC5;">15</span><span style="color:#D73A49;"> &amp;</span><span style="color:#6A737D;">     //&amp;符号会将命令放到后台运行，这时还可以进行其他的操作</span></span>
<span class="line"><span style="color:#24292E;">shutdown </span><span style="color:#D73A49;">+</span><span style="color:#005CC5;">5</span><span style="color:#6A737D;">             //5分钟后关机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>&amp;符号会将命令放到后台运行，这时还可以进行其他的操作</p></div><h2 id="halt" tabindex="-1">halt <a class="header-anchor" href="#halt" aria-label="Permalink to &quot;halt&quot;">​</a></h2><p>halt就是调用shutdown -h。halt执行时，杀死应用进程，执行sync系统调用，文件系统写操作完成后就会停止内核</p><h2 id="reboot" tabindex="-1">reboot <a class="header-anchor" href="#reboot" aria-label="Permalink to &quot;reboot&quot;">​</a></h2><p>reboot 的工作过程差不多跟halt一样，不过它是引发主机重启，而halt是关机</p><h2 id="init" tabindex="-1">init <a class="header-anchor" href="#init" aria-label="Permalink to &quot;init&quot;">​</a></h2><p>init 是所有进程的祖先，它的进程号始终为1，所以发送TERM信号给init会终止所有的 用户进程，守护进程等。shutdown 就是使用这种 机制。init定义了7个运行级别(runlevel)</p><p>所谓的init进程，它是一个由内核启动的用户级进程。内核自行启动（已经被载入内存，开始运行，并已初始化所有的设备驱动程序和数 据结构等）之后，就通过启动一个用户级程序init的方式，完成引导进程。所以,init始终是第一个进程（其进程编号始终为1）。内核会 在过去曾使用过init的几个地方查找它，它的正确位置（对Linux系统来说）是/sbin/init。如果内核找不到 init，它就会试着运行/bin/sh， 如果运行失败，系统的启动也会失败</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">init </span><span style="color:#005CC5;">0</span><span style="color:#6A737D;">          //关机</span></span>
<span class="line"><span style="color:#24292E;">init </span><span style="color:#005CC5;">6</span><span style="color:#6A737D;">          //重启</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="运行级别" tabindex="-1">运行级别 <a class="header-anchor" href="#运行级别" aria-label="Permalink to &quot;运行级别&quot;">​</a></h3><p>运行级就是操作系统当前正在运行的功能级别。这个级别从1到6 ，具有不同的功能</p><ul><li><code>0</code> 停机（千万不能把initdefault 设置为0 ）</li><li><code>1</code> 单用户模式</li><li><code>2</code> 多用户，没有 NFS（文件共享服务）</li><li><code>3</code> 完全多用户模式(标准的运行级)</li><li><code>4</code> 没有用到</li><li><code>5</code> X11 （xwindow)图形界面</li><li><code>6</code> 重新启动 （千万不要把initdefault 设置为6 ）</li></ul><p>查看当前运行级别</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">runlevel        </span><span style="color:#6A737D;">//查询当前运行级别</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="退出登录" tabindex="-1">退出登录 <a class="header-anchor" href="#退出登录" aria-label="Permalink to &quot;退出登录&quot;">​</a></h2><p>结束远程登录操作后，一定要退出登录</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>logout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,26)])])}const b=s(o,[["render",i]]);export{h as __pageData,b as default};
